nsenova-u1-fast\\\", \\\"display\\\": \\\"SenseNova U1 Fast\\\",\\n     \\\"speed\\\": \\\"~30s\\\", \\\"strengths\\\": \\\"Infographics & image generation (native 11 ratios)\\\"},\\n]\\n\\nDEFAULT_MODEL = \\\"sensenova-u1-fast\\\"\\n\\n\\nclass SensenovaImageProvider(ImageGenProvider):\\n    name = \\\"sensenova\\\"\\n    display_name = \\\"SenseNova\\\"\\n\\n    def __init__(self) -> None:\\n        self._api_key: str | None = None\\n        self._base_url = \\\"https://token.sensenova.cn/v1\\\"\\n\\n    # ------------------------------------------------------------------\\n    # Internal helpers\\n    # ------------------------------------------------------------------\\n\\n    def _get_api_key(self) -> str:\\n        if self._api_key:\\n            return self._api_key\\n        key = os.environ.get(\\\"SENSENOVA_API_KEY\\\", \\\"\\\").strip()\\n        if not key:\\n            raise ValueError(\\n                \\\"SENSENOVA_API_KEY environment variable is not set. \\\"\\n                \\\"Get your key at https://platform.sensenova.cn/console/keys\\\"\\n            )\\n        self._api_key = key\\n        return key\\n\\n    def _resolve_size(self, aspect_ratio: str) -> str:\\n        return _SIZE_MAP.get(aspect_ratio, _SIZE_MAP[\\\"landscape\\\"])\\n\\n    # ------------------------------------------------------------------\\n    # ImageGenProvider ABC\\n    # ------------------------------------------------------------------\\n\\n    def is_available(self) -> bool:\\n        try:\\n            self._get_api_key()\\n            return True\\n        except ValueError:\\n            return False\\n\\n    def list_models(self) -> List[Dict[str, Any]]:\\n        return _EXTRA_MODELS.copy()\\n\\n    def get_setup_schema(self) -> Dict[str, Any]:\\n        return {\\n            \\\"name\\\": \\\"SenseNova\\\",\\n            \\\"badge\\\": \\\"api\\\",\\n            \\\"tag\\\": \\\"SenseNova U1 \\u2014 infographics & image generation\\\",\\n            \\\"env_vars\\\": [\\n                {\\n                    \\\"key\\\": \\\"SENSENOVA_API_KEY\\\",\\n                    \\\"prompt\\\": \\\"SenseNova API Key (sk-...)\\\",\\n                    \\\"url\\\": \\\"https://platform.sensenova.cn/console/keys\\\",\\n                },\\n            ],\\n        }\\n\\n    def generate(\\n        self,\\n        prompt: str,\\n        aspect_ratio: str = DEFAULT_ASPECT_RATIO,\\n        **kwargs: Any,\\n    ) -> Dict[str, Any]:\\n        resolved_ratio = resolve_aspect_ratio(aspect_ratio)\\n        size = self._resolve_size(resolved_ratio)\\n\\n        try:\\n            api_key = self._get_api_key()\\n        except ValueError as e:\\n            return error_response(\\n                error=str(e),\\n                error_type=\\\"auth_error\\\",\\n                provider=self.name,\\n                model=DEFAULT_MODEL,\\n                prompt=prompt,\\n                aspect_ratio=resolved_ratio,\\n            )\\n\\n        headers = {\\n            \\\"Authorization\\\": f\\\"Bearer {api_key}\\\",\\n            \\\"Content-Type\\\": \\\"application/json\\\",\\n        }\\n\\n        payload = {\\n            \\\"model\\\": DEFAULT_MODEL,\\n            \\\"prompt\\\": prompt[:4096],   # max 4096 tokens enforced by API\\n            \\\"size\\\": size,\\n            \\\"n\\\": 1,\\n        }\\n\\n        try:\\n            resp = requests.post(\\n                f\\\"{self._base_url}/images/generations\\\",\\n                headers=headers,\\n                json=payload,\\n                timeout=120,\\n            )\\n        except Exception as exc:   # network / connection errors\\n            logger.exception(\\\"Sensenova request failed\\\")\\n            return error_response(\\n                error=f\\\"Request failed: {exc}\\\",\\n                error_type=\\\"network_error\\\",\\n                provider=self.name,\\n                model=DEFAULT_MODEL,\\n                prompt=prompt,\\n                aspect_ratio=resolved_ratio,\\n            )\\n\\n        if resp.status_code == 401:\\n            return error_response(\\n                error=\\\"Invalid API key. Check SENSENOVA_API_KEY.\\\",\\n                error_type=\\\"auth_error\\\",\\n                provider=self.name,\\n                model=DEFAULT_MODEL,\\n                prompt=prompt,\\n                aspect_ratio=resolved_ratio,\\n            )\\n\\n        if resp.status_code != 200:\\n            try:\\n                err_body = resp.json().get(\\\"error\\\", resp.text)\\n            except Exception:\\n                err_body = resp.text\\n            return error_response(\\n                error=f\\\"API error {resp.status_code}: {err_body}\\\",\\n                error_type=\\\"api_error\\\",\\n                provider=self.name,\\n                model=DEFAULT_MODEL,\\n                prompt=prompt,\\n                aspect_ratio=resolved_ratio,\\n            )\\n\\n        # Success \\u2014 extract image URL\\n        try:\\n            data = resp.json()\\n            image_url = data[\\\"data\\\"][0][\\\"url\\\"]\\n        except (KeyError, IndexError, ValueError) as exc:\\n            logger.exception(\\\"Failed to parse Sensenova response: %s\\\", resp.text)\\n            return error_response(\\n                error=f\\\"Unexpected response shape: {exc}\\\",\\n                error_type=\\\"parse_error\\\",\\n                provider=self.name,\\n                model=DEFAULT_MODEL,\\n                prompt=prompt,\\n                aspect_ratio=resolved_ratio,\\n            )\\n\\n        return success_response(\\n            image=image_url,\\n            model=DEFAULT_MODEL,\\n            prompt=prompt,\\n            aspect_ratio=resolved_ratio,\\n            provider=self.name,\\n        )\\n\"}"
